sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float phase;
uniform float angle;
uniform float spacing;
uniform float magnitude;
uniform float warpAngle;
uniform float speed;
uniform float screenSpace;
uniform float crossSpacing;
uniform float crossMagnitude;
uniform float origin;

half4 main(float2 coord) {
    float a = radians(angle);
    float b = radians(warpAngle);
    float2 da = float2(cos(a), sin(a));
    float2 db = float2(cos(b), sin(b));
    bool corner = origin > 0.5;
    float2 at = corner ? (coord - float2(screen.x, screen.y + screen.w)) / max(min(screen.z, screen.w), 1.0) : coord / max(screenSpace > 0.5 ? screen.zw : size, float2(1.0));
    float shift = corner ? phase : 0.0;
    float t = (corner ? 0.0 : 6.2831853 * phase) + time * speed;
    float unit = min(screen.z, screen.w) * 0.01;
    float2 move = magnitude * unit * sin(spacing * (dot(at, da) + shift) + t) * db;
    move += crossMagnitude * unit * sin(crossSpacing * (dot(at, db) + shift) + t) * da;
    return image.eval(coord + move);
}
